G=load()
def comps_cells(g, conn=8):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for p in range(H):
        for q in range(W):
            if g[p][q]==2 and (p,q) not in seen:
                dq=deque([(p,q)]); seen.add((p,q)); c=[]
                while dq:
                    a,b=dq.popleft(); c.append((a,b))
                    for dr in (-1,0,1):
                        for dc in (-1,0,1):
                            n=(a+dr,b+dc)
                            if 0<=n[0]<H and 0<=n[1]<W and g[n[0]][n[1]]==2 and n not in seen:
                                seen.add(n); dq.append(n)
                out.append(c)
    return out
